* BRICKS CHAT -- Model 2 (24x80) layout.
*
* Field-name contract shared with chatm4.map so the same REXX program
* can drive either. Per-row history fields are ROW01..ROW16, newest at
* the BOTTOM (closest to the input line). The INPUT field is the only
* UNPROT field -- the SEND MAP DATAONLY refresh path filters it out so
* the operator's in-progress typing is never repainted by a tick.
*
* All chrome and history fields start at col 0 so the leftmost visible
* character lands at col 1 (the attribute byte at col 0 displays as
* blank). ROW01..ROW16 / STATUS use LEN 78, the max safe length at
* col 0 -- col 79 stays untouched to dodge the wrap-to-next-row bug.
*
* Colors mirror /Users/moshe/tsu/chat.go:
*   BLUE/BRIGHT  -- title
*   TURQUOISE    -- clock, footer
*   YELLOW       -- topic / room name
*   RED          -- status / error line
*   GREEN        -- history rows, prompt
*   WHITE        -- operator input
MAP CHATM2 SIZE 24x80
  FIELD TITLE  AT 0,0  LEN 12 PROT BRIGHT COLOR=RED       "BRICKS CHAT"
  FIELD CLOCK  AT 0,36 LEN 8  PROT COLOR=TURQUOISE
  FIELD TOPIC  AT 0,50 LEN 28 PROT COLOR=YELLOW
  FIELD ROW01  AT 2,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW02  AT 3,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW03  AT 4,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW04  AT 5,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW05  AT 6,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW06  AT 7,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW07  AT 8,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW08  AT 9,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW09  AT 10,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW10  AT 11,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW11  AT 12,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW12  AT 13,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW13  AT 14,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW14  AT 15,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW15  AT 16,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW16  AT 17,0 LEN 78 PROT COLOR=GREEN
  FIELD STATUS AT 20,0 LEN 78 PROT COLOR=RED
  FIELD PROMPT AT 21,0 LEN 3  PROT BRIGHT COLOR=GREEN     "==>"
  INPUT INPUT  AT 21,10 LEN 62 UNDERSCORE COLOR=WHITE
  STOP         AT 21,75
  FIELD FOOTER AT 23,0 LEN 36 PROT COLOR=BLUE             "F3=exit  Enter=send"
  CURSOR AT INPUT
ENDMAP
